static unsigned checks=0;
static void Check(bool ok,const std::string& message,std::source_location at=std::source_location::current()){if(!ok)throw std::runtime_error(message+" at "+std::to_string(at.line()));++checks;}
struct ApplicationTestAccess {
    static bool New(Application& app,std::string& error){return app.NewSceneInternal(World::DataMode::HierarchyData,&error);}
    static bool Open(Application& app,const std::string& key,std::string& error){return app.OpenSceneInternal(key,true,&error);}
    static bool Project(Application& app,const std::filesystem::path& path,std::string& error){return app.OpenProjectInternal(path,Application::ProjectDecision::Discard,true,&error);}
};
namespace editor {struct EditorHierarchyTransformInspectorTestAccess {
    static void Select(Application& app,Entity e,bool ctrl=false){app.GetEditorLayer().SelectHierarchyEntity(app,e,ctrl,false,{});}
    static bool Edit(Application& app,Entity e,const TransformComponent& value){return app.GetEditorLayer().EditHierarchyLocal(app,e,value);}
    static bool Move(Application& app,const std::vector<Entity>& entities,Entity p){return app.GetEditorLayer().ReparentHierarchy(app,entities,p);}
    static const auto& Selection(Application& app){return app.GetEditorLayer().m_Selection;}
    static bool Draft(Application& app){return app.GetEditorLayer().m_HierarchyTransformDraft.has_value();}
    static const auto& Rows(Application& app){return app.GetEditorLayer().m_HierarchyTreeRows;}
};}
using Access=editor::EditorHierarchyTransformInspectorTestAccess;
static Entity Object(World& w,const std::string& id){auto e=w.CreateEntity();w.AddComponent<SceneIdentityComponent>(e).value=id;w.AddComponent<TransformComponent>(e);return e;}
static Entity Find(const World& w,const std::string& id){for(auto e:w.Entities())if(SceneSerializer::EntitySceneId(w,e)==id)return e;return {};}
static bool Near(const Matrix4& a,const Matrix4& b){for(int i=0;i<16;++i)if(std::abs(a[i]-b[i])>2e-5*std::max({1.,std::abs(a[i]),std::abs(b[i])}))return false;return true;}
static auto Capture(Application& app){return SceneSerializer::CaptureWorld(app.GetWorld(),app.GetSceneSettings());}
