static void Populate(World& w){auto p=Object(w,"parent"),c=Object(w,"child"),g=Object(w,"grandchild");Object(w,"other");w.AddComponent<RelationshipComponent>(c).parent="parent";w.AddComponent<RelationshipComponent>(g).parent="child";w.GetComponent<TransformComponent>(c)->position={1,0,0};w.GetComponent<TransformComponent>(g)->position={1,0,0};}
static ImVec2 RowPoint(Application& app,const std::string& id){auto* panel=ImGui::FindWindowByName("Hierarchy Tree");Check(panel&&panel->Active,"actual B1 Tree");ImGuiWindow* child=nullptr;for(auto* c:panel->DC.ChildWindows)if(c->Active&&std::string(c->Name).find("/Rows_")!=std::string::npos)child=c;Check(child,"Rows child");const auto& rows=Access::Rows(app);auto it=std::find_if(rows.begin(),rows.end(),[&](auto& r){return SceneSerializer::EntitySceneId(app.GetWorld(),r.entity)==id;});Check(it!=rows.end(),"visible tree row: "+id);return {child->WorkRect.Min.x+std::min(float(it->depth)*ImGui::GetStyle().IndentSpacing,child->WorkRect.GetWidth()*.45f)+ImGui::GetFontSize()*2.5f,child->DC.CursorStartPos.y+float(it-rows.begin())*ImGui::GetFrameHeightWithSpacing()+ImGui::GetFrameHeight()*.5f};}
static ImVec2 FieldPoint(int field){auto* panel=ImGui::FindWindowByName("Hierarchy Transform");Check(panel&&panel->Active,"actual safe H Inspector");auto p=panel->DC.CursorStartPos;return {p.x+25,p.y+5*ImGui::GetTextLineHeightWithSpacing()+field*(ImGui::GetFrameHeightWithSpacing()+ImGui::GetTextLineHeightWithSpacing())+ImGui::GetFrameHeight()*.5f};}
template<class F>static void Key(F& frame,ImGuiKey key,bool ctrl=false){SyntheticEditorInput::Key(ImGuiMod_Ctrl,ctrl);SyntheticEditorInput::Key(key,true);frame();SyntheticEditorInput::Key(key,false);SyntheticEditorInput::Key(ImGuiMod_Ctrl,false);frame();}
template<class F>static void Click(Application& app,F& frame,const std::string& id,bool ctrl=false){auto p=RowPoint(app,id);SyntheticEditorInput::Key(ImGuiMod_Ctrl,ctrl);SyntheticEditorInput::Position(p.x,p.y);frame();SyntheticEditorInput::Button(0,true);frame();SyntheticEditorInput::Button(0,false);frame();SyntheticEditorInput::Key(ImGuiMod_Ctrl,false);frame();}
